std::vector<Node> nodes;
for (RT::Finite_cells_iterator it = rt.finite_cells_begin(); it != rt.finite_cells_end(); ++it) {
    RT::Cell_handle cell = it;
    int edge_count_val = edge_count(cell, threshold);
    NodeType node_type = type_from_edge_count(edge_count_val);

    // Get vertex positions
    std::array<double, 3> position;
    for (int i = 0; i < 3; ++i) {
        position[i] = cell->vertex(i)->point().x();
    }

    // Get velocity (assuming velocity is computed per cell)
    Vector vel = velocity(cell);
    std::array<double, 3> velocity = {vel.x(), vel.y(), vel.z()};

    // Get mass (assuming mass is stored in vertices)
    double mass = vertices[cell->vertex(0)->index()].weight();

    nodes.push_back({position, velocity, mass, node_type});
}

// Handle infinite cells (walls) if needed
for (RT::Infinite_cells_iterator it = rt.infinite_cells_begin(); it != rt.infinite_cells_end(); ++it) {
    RT::Cell_handle cell = it;
    int edge_count_val = edge_count(cell, threshold);
    NodeType node_type = type_from_edge_count(edge_count_val);

    // Get vertex positions (infinite cells have 3 vertices too)
    std::array<double, 3> position;
    for (int i = 0; i < 3; ++i) {
        position[i] = cell->vertex(i)->point().x();
    }

    // For infinite cells, velocity might be zero or handled differently
    std::array<double, 3> velocity = {0.0, 0.0, 0.0};

    // Mass for infinite cells (walls) might be different
    double mass = 0.0; // or some default value

    nodes.push_back({position, velocity, mass, node_type});
}

return nodes;

